using AudioGuide.Data;
using Microsoft.EntityFrameworkCore;
using System.Text.RegularExpressions;
namespace AudioGuide.Business;
public record NarrationDto(int Id, int LocationId, int LanguageId, string LanguageCode, string Voice, string Name, string ShortDescription, string NarrationText, string HistoryText, string? AudioUrl, bool Fallback);
public interface IGuideService
{
    Task<List<Language>> Languages(bool admin = false); Task<object> Locations(string lang, bool admin = false); Task<NarrationDto> Narration(int id, string lang);
    Task<Location> SaveLocation(int id, Location p); Task DeleteLocation(int id); Task<Language> SaveLanguage(int id, Language p); Task DeleteLanguage(int id);
    Task<object> Translations(); Task<LocationTranslation> SaveTranslation(int id, LocationTranslation p, bool publish); Task DeleteTranslation(int id);
    Task<long> Log(PlayLog log); Task Complete(long id, string session); Task Feedback(Feedback f); Task<object> Statistics(); Task Audit(string user, string action);
}
public class GuideService(IRepository repo) : IGuideService
{
    private AppDbContext Db => repo.Db;
    public Task<List<Language>> Languages(bool admin = false) => Db.Languages.AsNoTracking().Where(x => admin || x.IsActive).OrderByDescending(x => x.IsDefault).ThenBy(x => x.Id).ToListAsync();
    public async Task<NarrationDto> Narration(int id, string lang)
    {
        if (!await Db.Locations.AnyAsync(x => x.Id == id && x.IsActive)) throw new AppError(404, "Không tìm thấy địa điểm");
        var q = Db.Translations.AsNoTracking().Include(x => x.Language).Where(x => x.LocationId == id && x.Status == "Published" && x.Language.IsActive);
        var t = await q.FirstOrDefaultAsync(x => x.Language.Code == lang) ?? await q.FirstOrDefaultAsync(x => x.Language.Code == "en") ?? throw new AppError(404, "Chưa có thuyết minh đã xuất bản, kể cả tiếng Anh");
        var audio = await Db.Audios.AsNoTracking().FirstOrDefaultAsync(x => x.TranslationId == t.Id);
        return new(t.Id, id, t.LanguageId, t.Language.Code, t.Language.TtsVoiceCode, t.Name, t.ShortDescription, t.NarrationText, t.HistoryText, audio?.FileUrl, t.Language.Code != lang);
    }
    public async Task<object> Locations(string lang, bool admin = false) { var ps = await Db.Locations.AsNoTracking().Where(x => admin || x.IsActive).OrderBy(x => x.DisplayOrder).ToListAsync(); if (admin) return ps; var result = new List<object>(); foreach (var p in ps) { NarrationDto? t = null; try { t = await Narration(p.Id, lang); } catch (AppError e) when (e.Status == 404) { } if (t != null) result.Add(new { p.Id, p.Slug, p.Latitude, p.Longitude, p.RadiusM, p.Priority, p.ImageUrl, p.OpeningHours, p.Address, p.DisplayOrder, t.Name, t.ShortDescription, t.LanguageCode, t.Fallback }); } return result; }
    public async Task<Location> SaveLocation(int id, Location p)
    {
        if (!Regex.IsMatch(p.Slug, "^[a-z0-9]+(?:-[a-z0-9]+)*$") || p.Slug.Length > 150 || !double.IsFinite(p.Latitude) || !double.IsFinite(p.Longitude) || Math.Abs(p.Latitude) > 90 || Math.Abs(p.Longitude) > 180 || p.RadiusM < 10 || p.RadiusM > 2000 || p.Address.Length > 500 || p.OpeningHours.Length > 500 || !SafeUrl(p.ImageUrl)) throw new AppError(400, "Địa điểm: slug, toạ độ, bán kính (10–2000m) hoặc URL ảnh không hợp lệ");
        if (await Db.Locations.AnyAsync(x => x.Slug == p.Slug && x.Id != id)) throw new AppError(409, "Slug đã tồn tại"); var x = id == 0 ? new Location() : await Db.Locations.FindAsync(id) ?? throw new AppError(404, "Không tìm thấy địa điểm"); x.Slug = p.Slug; x.Latitude = p.Latitude; x.Longitude = p.Longitude; x.RadiusM = p.RadiusM; x.Priority = p.Priority; x.ImageUrl = p.ImageUrl; x.OpeningHours = p.OpeningHours; x.Address = p.Address; x.DisplayOrder = p.DisplayOrder; x.IsActive = p.IsActive; x.UpdatedAt = DateTime.UtcNow; if (id == 0) Db.Locations.Add(x); await repo.Save(); return x;
    }
    public async Task DeleteLocation(int id) { var x = await Db.Locations.FindAsync(id) ?? throw new AppError(404, "Không tìm thấy địa điểm"); if (await Db.Translations.AnyAsync(t => t.LocationId == id) || await Db.PlayLogs.AnyAsync(t => t.LocationId == id) || await Db.Feedbacks.AnyAsync(t => t.LocationId == id)) throw new AppError(409, "Địa điểm đã có nội dung/lượt nghe. Hãy tắt trạng thái hoạt động để bảo toàn dữ liệu."); Db.Locations.Remove(x); await repo.Save(); }
    public async Task<Language> SaveLanguage(int id, Language p) { if (!Regex.IsMatch(p.Code, "^[a-z]{2,3}(-[A-Za-z]{2,4})?$") || string.IsNullOrWhiteSpace(p.Name) || string.IsNullOrWhiteSpace(p.NativeName) || !Regex.IsMatch(p.TtsVoiceCode, "^[a-z]{2,3}-[A-Za-z]{2,4}$")) throw new AppError(400, "Mã ngôn ngữ hoặc mã giọng đọc không hợp lệ"); if (p.IsDefault && !p.IsActive) throw new AppError(400, "Ngôn ngữ mặc định phải hoạt động"); if (await Db.Languages.AnyAsync(x => x.Code == p.Code && x.Id != id)) throw new AppError(409, "Mã ngôn ngữ đã tồn tại"); var x = id == 0 ? new Language() : await Db.Languages.FindAsync(id) ?? throw new AppError(404, "Không tìm thấy ngôn ngữ"); if (x.IsDefault && !p.IsDefault) throw new AppError(400, "Hãy đặt một ngôn ngữ khác làm mặc định trước"); if (p.IsDefault) foreach (var l in await Db.Languages.Where(l => l.IsDefault).ToListAsync()) l.IsDefault = false; x.Code = p.Code; x.Name = p.Name; x.NativeName = p.NativeName; x.TtsVoiceCode = p.TtsVoiceCode; x.IsActive = p.IsActive; x.IsDefault = p.IsDefault; if (id == 0) Db.Languages.Add(x); await repo.Save(); return x; }
    public async Task DeleteLanguage(int id) { var x = await Db.Languages.FindAsync(id) ?? throw new AppError(404, "Không tìm thấy ngôn ngữ"); if (x.IsDefault || await Db.Translations.AnyAsync(t => t.LanguageId == id) || await Db.PlayLogs.AnyAsync(t => t.LanguageId == id) || await Db.Feedbacks.AnyAsync(t => t.LanguageId == id)) throw new AppError(409, "Ngôn ngữ mặc định hoặc đã có dữ liệu. Hãy tắt thay vì xóa."); Db.Languages.Remove(x); await repo.Save(); }
    public async Task<object> Translations() => await Db.Translations.AsNoTracking().OrderBy(x => x.LocationId).Select(x => new { x.Id, x.LocationId, x.LanguageId, x.Name, x.ShortDescription, x.NarrationText, x.HistoryText, x.Status, x.IsMachineTranslated, x.UpdatedAt, AudioUrl = Db.Audios.Where(a => a.TranslationId == x.Id).Select(a => a.FileUrl).FirstOrDefault() }).ToListAsync();
    public async Task<LocationTranslation> SaveTranslation(int id, LocationTranslation p, bool publish) { if (string.IsNullOrWhiteSpace(p.Name) || p.Name.Length > 300 || string.IsNullOrWhiteSpace(p.NarrationText) || p.NarrationText.Length > 20000 || p.ShortDescription.Length > 2000 || p.HistoryText.Length > 20000 || !(p.Status is "Draft" or "Published")) throw new AppError(400, "Nội dung hoặc trạng thái không hợp lệ"); if (p.Status == "Published" && !publish) throw new AppError(403, "Chỉ Admin được duyệt xuất bản"); if (!await Db.Locations.AnyAsync(x => x.Id == p.LocationId) || !await Db.Languages.AnyAsync(x => x.Id == p.LanguageId)) throw new AppError(400, "Địa điểm/ngôn ngữ không tồn tại"); if (await Db.Translations.AnyAsync(x => x.LocationId == p.LocationId && x.LanguageId == p.LanguageId && x.Id != id)) throw new AppError(409, "Cặp địa điểm/ngôn ngữ đã tồn tại"); var x = id == 0 ? new LocationTranslation() : await Db.Translations.FindAsync(id) ?? throw new AppError(404, "Không tìm thấy nội dung"); if (id != 0 && (x.NarrationText != p.NarrationText || x.LanguageId != p.LanguageId)) { var old = await Db.Audios.FirstOrDefaultAsync(a => a.TranslationId == id); if (old != null) Db.Audios.Remove(old); } x.LocationId = p.LocationId; x.LanguageId = p.LanguageId; x.Name = p.Name; x.ShortDescription = p.ShortDescription; x.NarrationText = p.NarrationText; x.HistoryText = p.HistoryText; x.Status = p.Status; x.IsMachineTranslated = p.IsMachineTranslated; x.UpdatedAt = DateTime.UtcNow; if (id == 0) Db.Translations.Add(x); await repo.Save(); return x; }
    public async Task DeleteTranslation(int id) { var x = await Db.Translations.FindAsync(id) ?? throw new AppError(404, "Không tìm thấy nội dung"); Db.Translations.Remove(x); await repo.Save(); }
    public async Task<long> Log(PlayLog p) { if (!Guid.TryParse(p.SessionId, out _) || !(p.TriggerType is "GPS" or "Manual") || !await Db.Translations.AnyAsync(x => x.LocationId == p.LocationId && x.LanguageId == p.LanguageId && x.Status == "Published" && x.Location.IsActive && x.Language.IsActive)) throw new AppError(400, "Lượt nghe không hợp lệ"); var x = new PlayLog { SessionId = p.SessionId, LocationId = p.LocationId, LanguageId = p.LanguageId, TriggerType = p.TriggerType }; Db.PlayLogs.Add(x); await repo.Save(); return x.Id; }
    public async Task Complete(long id, string session) { var x = await Db.PlayLogs.FirstOrDefaultAsync(x => x.Id == id && x.SessionId == session) ?? throw new AppError(404, "Không tìm thấy lượt nghe"); x.Completed = true; await repo.Save(); }
    public async Task Feedback(Feedback p) { if (p.Rating < 1 || p.Rating > 5 || p.Comment.Length > 2000 || !await Db.Locations.AnyAsync(x => x.Id == p.LocationId && x.IsActive) || !await Db.Languages.AnyAsync(x => x.Id == p.LanguageId && x.IsActive)) throw new AppError(400, "Đánh giá không hợp lệ (1–5 sao, tối đa 2000 ký tự)"); Db.Feedbacks.Add(new() { LocationId = p.LocationId, LanguageId = p.LanguageId, Rating = p.Rating, Comment = p.Comment.Trim() }); await repo.Save(); }
    public async Task<object> Statistics() => new { total = await Db.PlayLogs.CountAsync(), completed = await Db.PlayLogs.CountAsync(x => x.Completed), byLocation = await Db.PlayLogs.GroupBy(x => x.LocationId).Select(g => new { id = g.Key, count = g.Count() }).ToListAsync(), byLanguage = await Db.PlayLogs.GroupBy(x => x.Language.Code).Select(g => new { language = g.Key, count = g.Count() }).ToListAsync(), byDay = await Db.PlayLogs.GroupBy(x => x.PlayedAt.Date).Select(g => new { date = g.Key, count = g.Count() }).OrderBy(x => x.date).ToListAsync(), feedbacks = await Db.Feedbacks.AsNoTracking().OrderByDescending(x => x.CreatedAt).Take(100).Select(x => new { x.Id, x.LocationId, x.Rating, x.Comment, x.CreatedAt }).ToListAsync() };
    public async Task Audit(string user, string action) { Db.AuditLogs.Add(new() { Username = user, Action = action }); await repo.Save(); }
    private static bool SafeUrl(string value) => value == "" || (value.StartsWith('/') && !value.StartsWith("//")) || (Uri.TryCreate(value, UriKind.Absolute, out var u) && u.Scheme == "https");
}
